{
  "sop_id": "SOP-018",
  "title": "Daily Operations Report",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create ticket and assign",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Collect data from sites",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Reconcile and compute KPIs",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Record incidents and actions",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Compile and publish report",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Incharge review of flagged reports",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Rework on rejection",
      "role": "Executor",
      "type": "rework"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always if KPI breach or safety event flagged; otherwise not required"
    }
  ],
  "dependencies": [],
  "rework_reasons": [
    "Wrong quantity",
    "Amount mismatch",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.95
}
